package com.example.evcharging.finance.settlement;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class SettlementCalculatorTest{@Test void conserve(){var r=SettlementCalculator.calculate(10001,List.of(new SettlementCalculator.RuleItem("OPERATOR","OP",7000),new SettlementCalculator.RuleItem("STATION_OWNER","SO",2000),new SettlementCalculator.RuleItem("PLATFORM","PLATFORM",1000)));assertEquals(10001,r.stream().mapToLong(SettlementCalculator.Allocation::amountFen).sum());}@Test void rejectOver(){assertThrows(IllegalArgumentException.class,()->SettlementCalculator.calculate(10000,List.of(new SettlementCalculator.RuleItem("A","1",7000),new SettlementCalculator.RuleItem("B","2",4000))));}}